def _text(value: object) -> str:
    if value is None:
        return ""
    if isinstance(value, (list, tuple)):
        return "\n".join(_text(item) for item in value if item is not None)
    if isinstance(value, dict):
        return _text(value.get("text", value.get("label", "")))
    return str(value)


def _items(value):
    return value if isinstance(value, (list, tuple)) else []


def _escape(value: object) -> str:
    return html.escape(_text(value), quote=True).replace("\n", "<br>")


_CITATION = re.compile(r"\[(?:(?P<case>评估\d+)|(?P<group>补充|补)?(?P<numbers>\d+(?:\s*[-–—,，、]\s*\d+)*))\]")


class _References:
    """Preview-only source namespaces; no fields are added to the callback."""

    def __init__(self, sections, *, primary_number=5, primary_chapter=5, aliases=None, cited_only=False,
                 ordered_references=False):
        self.blocks, self.targets, self.case_targets = {}, {}, {}
        self.unnumbered_blocks = set()
        self.aliases = aliases or {}
        self.cited_only = cited_only
        self.used_targets = set()
        groups = []
        for section in sections:
            if not isinstance(section, dict) or section.get("visible") is False:
                continue
            groups.extend(block for block in _items(section.get("blocks"))
                          if isinstance(block, dict) and block.get("kind") == "references")
        # In historical reports without a titled primary group the first
        # bibliography still owns ordinary numeric citations.
        primary = next((block for block in groups if re.match(rf"^{primary_chapter}\.{primary_number}\s*参考文献", _text(block.get("title")))),
                       groups[0] if groups else None)
        supplemental = 0
        for block in groups:
            if ordered_references and block.get("title") == "4.5 补充参考资料":
                self.unnumbered_blocks.add(id(block))
            if block is primary:
                namespace = "primary"
            else:
                supplemental += 1
                namespace = f"supplement-{supplemental}"
            self.blocks[id(block)] = namespace
            self.targets[namespace] = (set() if id(block) in self.unnumbered_blocks else
                                       {index for index, item in enumerate(_items(block.get("items")), 1)
                                        if isinstance(item, dict)})
            for index, item in enumerate(_items(block.get("items")), 1):
                if (id(block) not in self.unnumbered_blocks and isinstance(item, dict)
                        and (match := re.match(r"^\[(评估\d+)\]", _text(item.get("citation"))))):
                    self.case_targets[match[1]] = f"reference-{namespace}-{index}"

    def collect_visible(self, blocks):
        """Read only fields that the actual display block renders as citations.

        This runs after compact-layout projection. Hidden facts, score bands,
        internal metadata and bibliography self-citations cannot keep a source
        alive. Numbers remain their original indices even when items are hidden.
        """
        for block in blocks:
            kind = block.get("kind")
            if kind == "table":
                for row in _items(block.get("rows")):
                    for cell in _items(row.get("cells")) if isinstance(row, dict) else _items(row):
                        self.text(cell)
            elif kind == "list":
                for item in _items(block.get("items")):
                    self.text(item)
            elif kind == "cards" and block.get("_viewRole") == "focus":
                for item in _items(block.get("items")):
                    if isinstance(item, dict):
                        self.text(item.get("detail"))
            elif kind not in {"references", "facts", "cards", "bands"}:
                self.text(block.get("text"))

    def shows(self, block, index):
        namespace = self.blocks.get(id(block), "primary")
        return not self.cited_only or f"reference-{namespace}-{index}" in self.used_targets

    def text(self, value, *, group="primary"):
        raw = _text(value)
        output, cursor = [], 0
        for match in _CITATION.finditer(raw):
            output.append(_escape(raw[cursor:match.start()]))
            if match.group("case"):
                label = match.group("case")
                target = self.case_targets.get(label)
                if target:
                    self.used_targets.add(target)
                output.append(f'<a class="citation" href="#{target}">[{label}]</a>' if target else _escape(match.group()))
                cursor = match.end()
                continue
            namespace = "supplement-1" if match.group("group") else group
            available = self.targets.get(namespace, set())
            values = []
            valid = True
            for part in re.split(r"[,，、]", match.group("numbers")):
                bounds = re.split(r"[-–—]", part)
                if any(len(value.strip()) > 5 for value in bounds):
                    valid = False
                    break
                start, end = int(bounds[0]), int(bounds[-1])
                # Bound expansion and leave malformed/reversed ranges alone.
                if len(bounds) > 2 or end < start or end - start > 100:
                    valid = False
                    break
                values.extend(range(start, end + 1))
            alias = self.aliases.get(namespace, {})
            values = list(dict.fromkeys(alias.get(value, value) for value in values)) if alias else values
            if not valid or not any(value in available for value in values):
                output.append(_escape(match.group()))
            else:
                prefix = "补" if namespace.startswith("supplement-") else ""
                self.used_targets.update(f"reference-{namespace}-{value}" for value in values if value in available)
                links = [f'<a class="citation" href="#reference-{namespace}-{value}" aria-label="参考文献{prefix}{value}">{prefix}{value}</a>'
                         if value in available else str(value) for value in values]
                output.append("[" + ", ".join(links) + "]")
            cursor = match.end()
        output.append(_escape(raw[cursor:]))
        return "".join(output)


def _missing(value):
    """Only absent display values; real zero/negative Boolean results survive."""
    if value is None:
        return True
    if isinstance(value, str):
        return not value.strip()
    if isinstance(value, (tuple, list)):
        return all(_missing(item) for item in value)
    if isinstance(value, dict):
        return _missing(value.get("text", value.get("label")))
    return False


_AUXILIARY_TABLES = {
    ("本次检测方法与参考信息", ("检测指标", "本次检测方法", "实验室原始参考信息")):
        "本次资料未提供检测方法及实验室原始参考信息。",
    ("本次样本与质控记录", ("校验项目", "记录")):
        "本次资料未提供样本及质控记录。",
}


def _safe_url(value: object) -> str | None:
    if not isinstance(value, str) or any(ord(char) < 32 for char in value):
        return None
    try:
        parsed = urlsplit(value)
    except ValueError:
        return None
    if parsed.scheme.lower() not in {"http", "https"} or not parsed.hostname:
        return None
    return value


def _identifier(value: object, fallback: str) -> str:
    candidate = str(value or "")
    return candidate if re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]*", candidate) else fallback


_ABNORMAL_MARKER_EVALUATIONS = frozenset({
    "亚健康", "轻度", "中度", "重度", "升高", "轻度升高", "中度升高", "显著升高",
    "超出功能医学标准范围",
    "D-乳酸指标异常", "DAO指标异常", "LPS指标异常", "hs-CRP指标异常",
})


def _table(block: dict, references: _References | None = None, *, refined=False, template_risk_layout=False) -> str:
    columns = _items(block.get("columns"))
    auxiliary = _AUXILIARY_TABLES.get((_text(block.get("title")), tuple(_text(column) for column in columns)))
    data_rows = [_items(row.get("cells")) if isinstance(row, dict) else _items(row)
                 for row in _items(block.get("rows"))]
    if auxiliary and all(_missing(row[1:]) for row in data_rows):
        return f'<p class="empty auxiliary-empty">{_escape(auxiliary)}</p>'
    headings = "".join(f"<th scope=\"col\">{_escape(col)}</th>" for col in columns)
    rows = []
    for row in _items(block.get("rows")):
        current = isinstance(row, dict) and row.get("current") is True
        cells = _items(row.get("cells")) if isinstance(row, dict) else row
        if not isinstance(cells, (list, tuple)):
            continue
        result_index, evaluation_index = (2, 4) if columns == MARKER_VIEW_COLUMNS else (1, 3)
        abnormal = (refined and (columns == MARKER_VIEW_COLUMNS or tuple(columns) == MARKER_COLUMNS)
                    and len(cells) > evaluation_index and not _missing(cells[result_index])
                    and _text(cells[evaluation_index]).strip() in _ABNORMAL_MARKER_EVALUATIONS)
        rendered = []
        for index, cell in enumerate(cells):
            label = columns[index] if index < len(columns) else ""
            marker = '<span class="current-label">本次匹配</span>' if current and index == 0 else ""
            completed_qualitative = (tuple(columns) == RISK_COLUMNS and index == 1 and cell is None
                                     and len(cells) == 4 and cells[2] == QUALITATIVE_FOLLOWUP_LEVEL
                                     and not template_risk_layout)
            placeholder = None
            if _missing(cell):
                if auxiliary and index > 0:
                    placeholder = "未提供"
                elif tuple(columns) == RISK_COLUMNS and index in {1, 2}:
                    qualitative = len(cells) > 2 and ("（定性）" in str(cells[2]) or cells[2] == "专项资料不足")
                    placeholder = ("—" if template_risk_layout and cell is None else
                                   "定性随访" if completed_qualitative else
                                   "—" if qualitative and index == 1 else "未评估")
                elif tuple(columns) == MARKER_COLUMNS and index > 0:
                    placeholder = "—" if index == 4 else "待评估" if index == 3 else "未提供"
                elif columns == MARKER_VIEW_COLUMNS:
                    placeholder = "待评估" if index == 4 else "未提供"
                elif columns == RISK_VIEW_COLUMNS and index > 0:
                    placeholder = "资料不足" if index == 1 else "未提供"
                elif columns in (XU_ATTENTION_COLUMNS, XU_MODEL_COLUMNS) and index > 0:
                    placeholder = "—" if index == 1 else "资料不足" if index == 2 else "未提供"
            value = (f'<span class="risk-qualitative">{placeholder}</span>' if completed_qualitative else
                     f'<span class="empty">{placeholder}</span>' if placeholder else
                     references.text(cell) if references else _escape(cell))
            cell_class = (' class="marker-result-abnormal"' if abnormal and index == result_index else
                          ' class="marker-evaluation-abnormal"' if abnormal and index == evaluation_index else "")
            rendered.append(f'<td{cell_class} data-label="{html.escape(_text(label), quote=True)}">{value}{marker}</td>')
        css = ' class="current"' if current else ""
        rows.append(f"<tr{css}>{''.join(rendered)}</tr>")
    if not rows:
        return '<p class="empty">暂无可展示的结果。</p>'
    return f'<div class="table-wrap"><table class="responsive"><thead><tr>{headings}</tr></thead><tbody>{"".join(rows)}</tbody></table></div>'


def _block(block: dict, *, anchor: str | None = None, references: _References | None = None, refined=False,
           template_risk_layout=False) -> str:
    kind = block.get("kind")
    text = references.text if references else _escape
    title = f'<h3>{_escape(block["title"])}</h3>' if block.get("title") else ""
    if kind == "table":
        body = _table(block, references, refined=refined, template_risk_layout=template_risk_layout)
    elif kind == "facts":
        body = '<div class="facts">' + "".join(
            f'<div><div class="fact-label">{_escape(item.get("label"))}</div><div class="fact-value">{_escape(item.get("value"))}</div></div>'
            for item in _items(block.get("items")) if isinstance(item, dict)
            and _text(item.get("label")).strip() != "报告编号"
        ) + "</div>"
    elif kind == "cards":
        focus = block.get("_viewRole") == "focus"
        compact_ibfc = template_risk_layout and block.get("title") == "肠道屏障功能评分（IBFC）"
        cards_class = "cards focus-cards" if focus else "cards ibfc-meta-cards" if compact_ibfc else "cards"
        body = f'<div class="{cards_class}">' + "".join(
            f'<div class="card"><div class="fact-label">{_escape(item.get("label"))}</div><div class="value">{"未评估" if _missing(item.get("value")) else _escape(item.get("value"))}</div><p>{text(item.get("detail")) if focus else _escape(item.get("detail"))}</p></div>'
            for item in _items(block.get("items")) if isinstance(item, dict)
        ) + "</div>"
    elif kind == "bands":
        parts = []
        for item in _items(block.get("items")):
            if not isinstance(item, dict):
                continue
            selected = item.get("selected") is True
            css = "band selected" if selected else "band"
            selected_label = '<span class="selected-label">本次结果所在区间</span>' if selected else ""
            if template_risk_layout and block.get("title") == "屏障评分分级" and item.get("range") is None:
                parts.append(f'<div class="{css}"><b>{_escape(item.get("label"))}</b>{selected_label}</div>')
            else:
                parts.append(f'<div class="{css}"><b>{_escape(item.get("range"))}</b>{_escape(item.get("label"))}{selected_label}</div>')
        bands_class = f"bands bands-count-{len(parts)}" if template_risk_layout else "bands"
        body = f'<div class="{bands_class}">' + "".join(parts) + "</div>"
    elif kind == "list":
        body = '<ul class="report-list">' + "".join(f"<li>{text(item)}</li>" for item in _items(block.get("items"))) + "</ul>"
    elif kind == "callout":
        css = "callout caution" if block.get("tone") == "caution" else "callout"
        body = f'<div class="{css}">{text(block.get("text"))}</div>'
    elif kind == "references":
        entries = []
        for index, item in enumerate(_items(block.get("items")), 1):
            if not isinstance(item, dict):
                continue
            if references and not references.shows(block, index):
                continue
            url = _safe_url(item.get("url") or item.get("link"))
            link = f'<a href="{html.escape(url, quote=True)}" target="_blank" rel="noopener noreferrer">来源</a>' if url else ""
            detail = resolve_reference_citation(item)
            if detail is None:
                detail = "参考资料"
            if references and references.cited_only and isinstance(detail, str):
                # The named token is an internal citation identity already
                # resolved by _References. Show one bibliography number only,
                # without mutating the source or its inline-link mapping.
                detail = re.sub(r"^\[评估\d+\]\s*", "", detail) or "参考资料"
            metadata = " · ".join(_text(item.get(key)) for key in ("year", "publisher", "doi", "location") if item.get(key) is not None and item.get(key) != "")
            namespace = references.blocks.get(id(block), "primary") if references else "primary"
            prefix = "补" if namespace.startswith("supplement-") else ""
            number = "" if references and id(block) in references.unnumbered_blocks else (
                f'<span class="reference-index">[{prefix}{index}]</span>')
            entries.append(f'<li id="reference-{namespace}-{index}">{number}{_escape(detail)}{("<br>" + _escape(metadata)) if metadata else ""}{link}</li>')
        if not entries and references and references.cited_only:
            return ""
        body = '<ol class="bibliography">' + "".join(entries) + "</ol>"
    elif (kind == "paragraph" and template_risk_layout
          and re.fullmatch(r"2\.\d+ 本章小结", block.get("title") or "")):
        # Keep one wire paragraph/text field. Plain-text blank lines become
        # visible paragraphs without rewriting the embedded callback report.
        body = "".join(f'<p>{text(part)}</p>' for part in _text(block.get("text")).split("\n\n"))
    else:
        body = f'<p>{text(block.get("text"))}</p>'
    identifier = f' id="{html.escape(anchor, quote=True)}"' if anchor else ""
    return f'<div class="block"{identifier}>{title}{body}</div>'


def _subsection(block: dict, section_id: str, chapter_number: int):
    """Derive preview-only anchors without adding fields to the frozen JSON."""
    title = _text(block.get("title"))
    match = re.match(r"^([1-5])\.([1-9]\d*)(?=\s|[、.])", title)
    if not match or int(match.group(1)) != chapter_number:
        return None
    return f"{section_id}-{match.group(1)}-{match.group(2)}", title


def _interpretation_blocks(report: dict, fallback: list) -> list:
    """Resolve presentation order against the immutable candidate whitelist."""
    return resolve_interpretation_blocks(report, fallback)


def render_report_html(report: dict, *, template_version: str | None = None,
                       template_archive_dir: str | Path | None = None) -> str:
    """Render a ReportDocument without executing or trusting any source markup."""
    if not isinstance(report, dict):
        raise TypeError("report must be a dictionary")
    # Display-only frontend copy. Keep the original callback in report-data so
    # local preview never pretends static content was returned by the API.
    callback_report = report
    selected_template = resolve_display_template(report, template_version)
    capabilities = display_capabilities(selected_template)
    latest, xu = capabilities.compact_layout, capabilities.xu_review
    refined = capabilities.refined_fixed_layout
    clean_review = capabilities.clean_review_layout
    source_stage_layout = capabilities.source_stage_layout
    archive_options = {"template_archive_dir": template_archive_dir} if template_archive_dir is not None else {}
    report = expand_dynamic_report(report, template_version=selected_template, **archive_options)
    meta = report.get("meta") if isinstance(report.get("meta"), dict) else {}
    title = meta.get("title") or "肠道屏障功能与炎症综合评估报告"
    if capabilities.barrier_only_layout:
        title = "肠道屏障功能评估报告"
    elif latest:
        title = "肠道屏障功能与炎症状态评估报告"
    rendered_sections = []
    navigation = []
    subsection_navigation = {}
    sections = _items(report.get("sections"))
    if latest:
        sections = arrange_sections(sections, clean_review_layout=clean_review,
                                    canonical_dynamic_layout=capabilities.canonical_dynamic_layout)
    references = _References(sections, primary_number=capabilities.primary_reference_number,
                             primary_chapter=4 if capabilities.canonical_dynamic_layout else 5,
                             aliases=report.get("_referenceAliases") if refined else None,
                             cited_only=clean_review and not capabilities.ordered_reference_layout,
                             ordered_references=capabilities.ordered_reference_layout)
    five_chapters = supports_report_graphics(sections, template_version=selected_template)
    visible_blocks = {}
    if clean_review:
        visible_blocks = (display_blocks(sections, xu=xu, source_stage_layout=source_stage_layout,
                                         word_review_layout=capabilities.word_review_layout,
                                         canonical_dynamic_layout=capabilities.canonical_dynamic_layout,
                                         template_risk_layout=capabilities.template_risk_layout)
                          if latest and five_chapters else
                          {id(block): block for section in sections if isinstance(section, dict)
                           and section.get("visible") is not False
                           for block in _items(section.get("blocks")) if isinstance(block, dict)})
        references.collect_visible(block for block in visible_blocks.values() if block is not None)
    figure_count = 0

    def number_figures(fragment):
        """Only v3 uses contiguous IDs; gaps in historical releases stay frozen."""
        nonlocal figure_count
        if not xu:
            return fragment

        def replace(match):
            nonlocal figure_count
            figure_count += 1
            return (f'<figure class="report-figure" id="figure-{figure_count}"><figcaption>'
                    f'<span class="figure-number">图 {figure_count}</span>')

        return re.sub(r'<figure class="report-figure" id="figure-\d+"><figcaption>'
                      r'<span class="figure-number">图 \d+</span>', replace, fragment)

    for index, section in enumerate(sections, 1):
        if not isinstance(section, dict) or section.get("visible") is False:
            continue
        section_id = _identifier(section.get("id"), f"section-{index}")
        heading = section.get("title") or "评估结果"
        heading_tag = "h1" if not five_chapters and not rendered_sections else "h2"
        navigation.append((section_id, heading))
        subtitle = f'<p class="subtitle">{_escape(section.get("subtitle"))}</p>' if section.get("subtitle") else ""
        section_blocks = _items(section.get("blocks"))
        if section.get("id") == "interpretation":
            section_blocks = _interpretation_blocks(report, section_blocks)
        blocks = number_figures(before_section(section_id, sections,
            template_version=selected_template, clean_review_layout=clean_review)) if five_chapters else ""
        anchors = set()
        subsections = []
        for block_index, block in enumerate(section_blocks):
            if not isinstance(block, dict):
                continue
            if (five_chapters and capabilities.canonical_dynamic_layout
                    and section_id == "disease_risks"
                    and (is_risk_overview(block) if capabilities.template_risk_layout else is_attention_overview(block))):
                # This ordinary callback table supplies the chapter overview
                # graphic. Keep source rows in report-data and detailed tables
                # below, without repeating a second visible overview table.
                blocks += number_figures(after_block(section_id, block, sections,
                    template_version=selected_template, clean_review_layout=clean_review,
                    source_stage_layout=source_stage_layout))
                continue
            # Compact blocks only when the matching cover and graphics exist.
            # A partial/unknown document must retain its original facts/cards.
            view_block = (visible_blocks.get(id(block)) if clean_review else
                          display_block(section_id, block, sections, xu=xu, source_stage_layout=source_stage_layout)
                          if latest and five_chapters else block)
            if view_block is None:
                blocks += number_figures(after_block(section_id, block, sections, latest=True,
                    template_version=selected_template, clean_review_layout=clean_review,
                    source_stage_layout=source_stage_layout)) if five_chapters else ""
                continue
            previous_block = section_blocks[block_index - 1] if block_index else None
            if (capabilities.canonical_dynamic_layout and section_id == "disease_risks"
                    and view_block.get("kind") == "list"
                    and re.fullmatch(r"2\.\d+ 本章小结", view_block.get("title") or "")
                    and isinstance(previous_block, dict) and previous_block.get("kind") == "paragraph"
                    and previous_block.get("title") == view_block.get("title")):
                # The callback keeps both established list keys and the new
                # prose block; adjacent summary parts share one visible title.
                view_block = {**view_block, "title": None}
            if (clean_review and view_block.get("kind") == "references"
                    and not any(isinstance(item, dict) and references.shows(view_block, i)
                                for i, item in enumerate(_items(view_block.get("items")), 1))):
                # Do not create an empty bibliography heading or a dead TOC
                # target after filtering. Other appendix content stays intact.
                continue
            subsection = _subsection(view_block, section_id, index) if five_chapters else None
            anchor = None
            if subsection and subsection[0] not in anchors:
                anchor = subsection[0]
                anchors.add(anchor)
                subsections.append(subsection)
            rendered_block = _block(view_block, anchor=anchor, references=references, refined=refined,
                                    template_risk_layout=capabilities.template_risk_layout)
            graphic_first = (capabilities.template_risk_layout and section_id == "overview"
                             and block.get("kind") == "cards"
                             and block.get("title") == "肠道屏障功能评分（IBFC）")
            if graphic_first and five_chapters:
                # V11 keeps conclusion -> figure -> compact clinical metadata.
                # The unmodified callback still owns all original card values.
                blocks += number_figures(after_block(section_id, block, sections, latest=latest,
                    template_version=selected_template, clean_review_layout=clean_review,
                    source_stage_layout=source_stage_layout))
            if latest and view_block.get("_viewRole") == "focus" and view_block.get("items"):
                rendered_block = ('<figure class="report-figure" id="figure-4"><figcaption>'
                                  '<span class="figure-number">图 4</span>重点关注方向</figcaption>'
                                  + rendered_block + '</figure>')
            blocks += rendered_block
            blocks += number_figures(after_block(section_id, block, sections, latest=latest,
                template_version=selected_template, clean_review_layout=clean_review,
                source_stage_layout=source_stage_layout)) if five_chapters and not graphic_first else ""
        subsection_navigation[section_id] = subsections
        rendered_sections.append(
            f'<section class="report-section" id="{section_id}">'
            f'<div class="folio"><span>{_escape(title)}</span></div>'
            f'<div class="heading"><span class="section-no">{index:02d}</span><div><{heading_tag}>{_escape(heading)}</{heading_tag}>{subtitle}</div></div>{blocks}</section>'
        )
    nav = "".join(f'<a href="#{identifier}">{_escape(label)}</a>' for identifier, label in navigation)
    cover = ""
    if five_chapters:
        entries = []
        for index, (identifier, label) in enumerate(navigation, 1):
            subsections = "".join(f'<li><a href="#{anchor}">{_escape(subtitle)}</a></li>'
                                  for anchor, subtitle in subsection_navigation[identifier])
            nested = f'<ul class="toc-subsections">{subsections}</ul>' if subsections else ""
            entries.append(f'<li><a href="#{identifier}"><span class="toc-no">{index:02d}</span><span class="toc-title">{_escape(label)}</span></a>{nested}</li>')
        contents = "".join(entries)
        lead = ("检测综述 · 疾病风险评估 · 分层修复方案 · 附录与参考依据"
                if capabilities.canonical_dynamic_layout else
                "检测综述 · 疾病风险评估 · 分层修复方案 · 屏障与慢性炎症 · 附录与参考依据"
                if chapter_layout(sections) == "reordered" else
                "检测综述 · 屏障与炎症机制 · 疾病风险评估 · 个体化干预 · 质控与参考依据")
        cover_facts = []
        for section in sections:
            if not isinstance(section, dict) or section.get("id") != "overview" or section.get("visible") is False:
                continue
            for block in _items(section.get("blocks")):
                if not isinstance(block, dict) or block.get("kind") != "facts" or block.get("title") != "受检者信息":
                    continue
                for item in _items(block.get("items")):
                    cover_labels = COVER_FACT_LABELS if latest else {"姓名", "性别", "年龄", "检测日期", "报告日期"}
                    if isinstance(item, dict) and item.get("label") in cover_labels and not _missing(item.get("value")):
                        cover_facts.append(f'<div><span class="fact-label">{_escape(item["label"])}</span><strong>{_escape(item["value"])}</strong></div>')
        patient = '<div class="cover-patient">' + "".join(cover_facts) + '</div>' if cover_facts else ""
        cover = (f'<div class="report-section cover"><p class="cover-kicker">INTESTINAL BARRIER · INTEGRATED ASSESSMENT</p>'
                 f'<h1>{_escape(title)}</h1><p class="cover-lead">{_escape(lead)}</p>'
                 f'{patient}'
                 f'<nav class="toc" aria-label="报告目录"><h2>报告目录</h2><ol>{contents}</ol></nav></div>')
    # JSON is a data island, not an executable script. Escape HTML-significant
    # characters so source text cannot close its script element.
    data = json.dumps(callback_report, ensure_ascii=False, allow_nan=False).replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    refined_css = (_REFINED_CSS.replace("肠道屏障功能与炎症状态评估报告", "肠道屏障功能评估报告")
                   if capabilities.barrier_only_layout else _REFINED_CSS)
    return (
        '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width,initial-scale=1">'
        '<link rel="icon" href="data:,">'
        f'<title>{_escape(title)}</title><style>{_CSS}{_LATEST_CSS if latest else ""}{_XU_CSS if xu else ""}{refined_css if refined else ""}{_SOURCE_STAGE_CSS if source_stage_layout else ""}{_TEMPLATE_RISK_CSS if capabilities.template_risk_layout else ""}</style></head><body>'
        f'<header class="toolbar"><div class="toolbar-inner"><span class="wordmark">肠道屏障综合评估</span><nav aria-label="报告导航">{nav}</nav><button type="button" class="print" id="print-report">打印 / 存为 PDF</button></div></header>'
        f'<main class="report">{cover}{"".join(rendered_sections)}<p class="end-note">本报告为辅助评估与健康管理建议，具体医疗措施由医师结合临床情况确认。</p></main>'
        f'<script type="application/json" id="report-data">{data}</script>'
        '<script>document.getElementById("print-report").addEventListener("click",function(){window.print();});</script></body></html>'
    )
